import{_ as i,o as t,c as l,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Guide To Getting Started With Developing in Ceph - Jonathan Bailey & Alex Ainscow, IBM","description":"","frontmatter":{"title":"Guide To Getting Started With Developing in Ceph - Jonathan Bailey & Alex Ainscow, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-19T00:00:00.000Z","tags":["Ceph","开发者指南","分布式存储","CephFS","Rados"],"categories":["技术文档","存储解决方案","开源软件","Ceph社区","开发最佳实践"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Guide_To_Getting_Started_With_Developing_in_Ceph_-_Jonathan_Bailey_Alex_Ainscow_IBM.md","filePath":"posts/2025/Guide_To_Getting_Started_With_Developing_in_Ceph_-_Jonathan_Bailey_Alex_Ainscow_IBM.md","lastUpdated":1780459816000}'),o={name:"posts/2025/Guide_To_Getting_Started_With_Developing_in_Ceph_-_Jonathan_Bailey_Alex_Ainscow_IBM.md"};function n(r,e,_,h,p,s){return t(),l("div",null,[...e[0]||(e[0]=[a('<p>本次会议由IBM存储团队的John和Alex主持，旨在为新开发者提供Ceph分布式存储系统的入门指导。以下是对会议内容的详细总结：</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次会议主要讨论了Ceph社区的交流方式、开发环境的搭建、代码结构与开发入门、测试与验证以及贡献代码的流程。</p><h3 id="关键讨论议题" tabindex="-1">关键讨论议题 <a class="header-anchor" href="#关键讨论议题" aria-label="Permalink to &quot;关键讨论议题&quot;">​</a></h3><ol><li><p><strong>Ceph社区与文化</strong></p><ul><li>Ceph社区由全球开发者、用户和企业组成，强调开放协作和知识共享。</li><li>交流渠道包括邮件列表、Slack/IRC、虚拟会议和线下活动，如Ceph Days全球会议。</li></ul></li><li><p><strong>开发环境搭建</strong></p><ul><li>推荐使用John Mulligan的<a href="https://github.com/ceph/ceph-container" target="_blank" rel="noreferrer">容器脚本</a>来简化Linux/macOS环境配置。</li><li>构建过程包括安装依赖、配置CMake和编译代码。</li><li>支持使用<code>clang</code>/<code>GCC</code>，并提供优化构建的选项。</li></ul></li><li><p><strong>代码结构与开发入门</strong></p><ul><li>介绍Ceph的核心组件路径，如OSD、librados和ceph-test。</li><li>推荐从<code>good first issue</code>标签或编写测试工具开始入门。</li><li>提供学习资源，如Ceph YouTube频道的组件深度解析视频。</li></ul></li><li><p><strong>测试与验证</strong></p><ul><li>介绍单机测试和多集群交互测试的方法。</li><li>强调性能与压力测试的重要性，并介绍CBT和Teuthology等工具。</li><li>指出自定义测试的重要性，如验证Erasure Coding场景。</li></ul></li><li><p><strong>贡献代码流程</strong></p><ul><li>强调PR提交规范，如分层提交和社区评审。</li><li>介绍QA流程，包括自动化测试和专家日志审查。</li><li>说明首次PR可能耗时较长，小型修复更快合入。</li></ul></li></ol><h3 id="行动计划" tabindex="-1">行动计划 <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;行动计划&quot;">​</a></h3><ul><li>新开发者应加入邮件列表和Slack频道，使用容器脚本搭建环境，尝试构建并运行<code>vstart.sh</code>集群。</li><li>功能开发者应针对<code>main</code>分支开发，编写测试用例，并参与组件会议。</li><li>社区协作包括参与组件会议、分享进展和获取反馈。</li></ul><h3 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h3><p>会议强调了Ceph社区的开放性和技术深度，提供了从环境搭建到代码贡献的完整路径。关键建议包括早沟通、小步迭代和重视测试。对于复杂功能，需通过社区协作确保安全性和兼容性。</p><p><strong>资源链接</strong>：</p><ul><li><a href="https://ceph.io/community/calendar/" target="_blank" rel="noreferrer">Ceph社区日历</a></li><li><a href="https://github.com/ceph/ceph" target="_blank" rel="noreferrer">GitHub仓库</a></li><li><a href="https://www.youtube.com/user/cephstorage" target="_blank" rel="noreferrer">YouTube教学</a></li></ul>',11)])])}const u=i(o,[["render",n]]);export{c as __pageData,u as default};
